// Transparent-PNG elements (public/elements, generated by apps/api/scripts/make_elements.py —
// recreated looks, nothing cut from reference photos). Loaded once, drawn as stickers.
import type { Ctx } from "./draw";
import PROP_LIST from "./props.json";

export const ELEMENT_FILES = {
  kiss: { file: "kiss-print", w: 900, h: 545 },
  kissblur: { file: "kiss-blur", w: 1140, h: 785 },
  folder: { file: "folder", w: 256, h: 224 },
  cursor: { file: "cursor", w: 168, h: 238 },
  warning: { file: "warning", w: 260, h: 260 },
  brackets: { file: "focus-brackets", w: 400, h: 300 },
  rec: { file: "rec", w: 300, h: 110 },
  tornstrip: { file: "torn-strip", w: 1200, h: 220 },
  cat: { file: "cat-doodle", w: 260, h: 260 },
  faceheart: { file: "face-heart", w: 120, h: 120 },
  barcode: { file: "barcode", w: 420, h: 170 },
  chromestar: { file: "chrome-star", w: 300, h: 300 },
  chromesparkle: { file: "chrome-sparkle", w: 300, h: 300 },
  exclaim: { file: "exclaim", w: 220, h: 260 },
  anger: { file: "anger", w: 220, h: 220 },
  owocat: { file: "owo-cat", w: 300, h: 280 },
  headcat: { file: "headphone-cat", w: 280, h: 300 },
} as const;
export type ElementKind = keyof typeof ELEMENT_FILES;

/** Bump when any element PNG changes, so browsers don't keep a cached old copy. */
const ELEMENTS_VERSION = 3;

const images = new Map<ElementKind, HTMLImageElement>();
let ready: Promise<void> | null = null;

/** Load every element image (no-op outside the browser). */
export function elementsReady(): Promise<void> {
  if (typeof Image === "undefined") return Promise.resolve();
  ready ??= Promise.all(
    (Object.keys(ELEMENT_FILES) as ElementKind[]).map(
      (k) =>
        new Promise<void>((resolve) => {
          const img = new Image();
          img.onload = () => {
            images.set(k, img);
            resolve();
          };
          img.onerror = () => resolve(); // a missing element just doesn't draw
          img.src = `/elements/${ELEMENT_FILES[k].file}.png?v=${ELEMENTS_VERSION}`;
        }),
    ),
  )
    .then(() =>
      Promise.all(
        (Object.keys(SCREENS) as (keyof typeof SCREENS)[]).map(
          (k) =>
            new Promise<void>((resolve) => {
              const img = new Image();
              img.onload = () => {
                screens.set(k, img);
                resolve();
              };
              img.onerror = () => resolve();
              img.src = `${SCREENS[k]}?v=${ELEMENTS_VERSION}`;
            }),
        ),
      ),
    )
    .then(() => undefined);
  return ready;
}

/** Full-Story overlay images (green-screen templates keyed by apps/api/scripts/key_template.py). */
export const SCREENS = {
  whatsapp: "/templates/whatsapp-screen.png",
  playlist: "/templates/playlist-screen.png",
  appswitch: "/templates/appswitch-screen.webp",
  filmslant: "/templates/filmslant-screen.webp",
} as const;
const screens = new Map<keyof typeof SCREENS, HTMLImageElement>();

export function drawScreen(ctx: Ctx, name: keyof typeof SCREENS, w: number, h: number): void {
  const img = screens.get(name);
  if (img) ctx.drawImage(img, 0, 0, w, h);
}

// ---- Prop photos (public/props, openly licensed; credits in props.json), loaded on demand ----
export interface Prop {
  id: string;
  file: string;
  w: number;
  h: number;
  title: string;
  creator: string;
  creatorUrl: string;
  license: string;
  licenseUrl: string;
  source: string;
}
export const PROPS = PROP_LIST as Prop[];
const props = new Map<string, Promise<HTMLImageElement | null>>();
const loadedProps = new Map<string, HTMLImageElement>();
const listeners = new Set<() => void>();

/** Called when a lazily loaded asset (prop photo) arrives, so canvases can redraw. */
export function onAssetLoaded(cb: () => void): () => void {
  listeners.add(cb);
  return () => listeners.delete(cb);
}

/** Tell canvases a lazily loaded asset (prop photo, web font) is ready. */
export function assetLoaded(): void {
  listeners.forEach((f) => f());
}

export function propReady(id: string): Promise<HTMLImageElement | null> {
  if (typeof Image === "undefined") return Promise.resolve(null);
  let p = props.get(id);
  if (!p) {
    const prop = PROPS.find((x) => x.id === id);
    p = new Promise((resolve) => {
      if (!prop) return resolve(null);
      const img = new Image();
      img.onload = () => {
        loadedProps.set(id, img);
        assetLoaded();
        resolve(img);
      };
      img.onerror = () => resolve(null);
      img.src = prop.file;
    });
    props.set(id, p);
  }
  return p;
}

/** The prop image if loaded (starts loading it otherwise). */
export function propImage(id: string): HTMLImageElement | null {
  const img = loadedProps.get(id);
  if (!img) void propReady(id);
  return img ?? null;
}

export const isElement = (kind: string): kind is ElementKind => kind in ELEMENT_FILES;

/** Draw an element centred at the origin with its longest side = `size`. */
export function drawElement(ctx: Ctx, kind: ElementKind, size: number): void {
  const img = images.get(kind);
  if (!img) return;
  const { w, h } = ELEMENT_FILES[kind];
  const k = size / Math.max(w, h);
  ctx.drawImage(img, (-w * k) / 2, (-h * k) / 2, w * k, h * k);
}
